window.kbPageData["views/entry/k-0d4ccc6ba461f479"] = {"key":"entry/k-0d4ccc6ba461f479","state":{"route":"entry/k-0d4ccc6ba461f479"},"node":{"id":"k-0d4ccc6ba461f479","mode":"k","title":"意识的本质","type":"原理与机制","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["唯物论 · 意识的本质"],"qs":["政治理论必刷100题#10"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["原理与机制"],"出处性质":["专项题解析","理论手册"],"学科":["哲学","政治理论"],"来源主题":["马克思主义哲学"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"在马克思主义哲学中，意识是人脑的机能，是客观世界的主观映象。人能够能动地反映客观世界，对经验材料进行选择和加工。","review":{"definition":"在马克思主义哲学中，意识是人脑的机能，是客观世界的主观映象。人能够能动地反映客观世界，对经验材料进行选择和加工。","explanation":"题中的软件可以按给定主题和要求生成连贯文字，作家则能把自身的生活体验和情感感悟融入文章。①以这种差异说明人类意识的能动性和创造性，生成文字这一表现本身不足以说明软件具有人类意识。","references":[],"evidence":"意识是人脑的机能和属性，是客观世界的主观映象","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"177ce0d26f22cba6","label":"唯物论 · 意识的本质","topic":"马克思主义哲学","category":"非时政","text":"二、意识的本质\n人脑对客观存在的主观映象。\n意识是人脑特有的机能。人脑是产生意识的物质器官。\n（粉笔敲黑板：是人脑而非大脑）","source":{"doc":"3ccc56f4000d1642c2d1","first":2,"last":2,"page":2,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"政治理论必刷100题#10":{"paper":"政治理论必刷100题","n":10,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",3],"asrc":["国省考政治理论必刷100题.pdf",36],"card":"ad6234b577e056076e36c1f7","links":[{"id":"k-0d4ccc6ba461f479","role":"直接考查","why":"用意识的产生基础和本质判断人工智能生成文本与人类意识的关系。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-0d4ccc6ba461f479":[["政治理论必刷100题#10"]]}};
